-- SADT, lote 97 (F3.5, 05-SADT linha 25): parâmetros do diagnóstico por setor semeados no catálogo tipado
-- (parametro_definicao, chave sadt.<nome> e sadt.<setor>.<nome>): numeração do exame, impressão do laudo e da etiqueta,
-- obrigatoriedades do pedido, mais os parâmetros sadt.* do produto que já estavam no contrato e não tinham linha no
-- banco (a leitura GET /api/sadt/parametros devolvia lista vazia e a tela de parâmetros não gravava). Valem para a rede
-- e o estabelecimento, com vigência em parametro_valor. Sem tabela nova. Só para frente; idempotente (chave única).
INSERT INTO modulo_sistema (codigo, descricao, ativo, ordem, criado_em)
  SELECT 'sadt', 'Diagnóstico e terapia', TRUE, 0, CURRENT_TIMESTAMP(3) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM modulo_sistema WHERE codigo = 'sadt');
INSERT IGNORE INTO parametro_definicao (chave, modulo_sistema_id, descricao, tipo, valor_padrao, permite_rede, permite_estabelecimento, permite_unidade, permite_perfil, permite_usuario, critico, obrigatorio, minimo, maximo, formato_expressao, formato_mensagem, area_dona, fundamento, rota_tela, ativo, criado_em)
  SELECT x.chave, m.id, x.descricao, x.tipo, x.padrao, TRUE, TRUE, FALSE, FALSE, FALSE, x.critico, FALSE, x.minimo, x.maximo, x.formato,
         CASE WHEN x.formato IS NULL THEN NULL ELSE 'Use até 10 letras maiúsculas, dígitos ou hífen.' END, x.dono,
         'Ficha F3.5, 05-SADT linha 25 (parâmetros do diagnóstico por setor, com vigência)', '/administracao/parametros', TRUE, CURRENT_TIMESTAMP(3)
  FROM (
    SELECT 'sadt.criticoEscalonarMinutos' AS chave, 'Minutos sem ciência do valor crítico até subir do responsável ao plantonista' AS descricao, 'inteiro' AS tipo, '30' AS padrao, '5' AS minimo, '240' AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.repeticaoMinimaHoras' AS chave, 'Intervalo mínimo em horas entre dois pedidos do mesmo exame para o mesmo paciente' AS descricao, 'inteiro' AS tipo, '24' AS padrao, '0' AS minimo, '720' AS maximo, NULL AS formato, 'laboratório' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.portalTentativas' AS chave, 'Tentativas erradas de acesso ao portal de resultados antes do bloqueio temporário' AS descricao, 'inteiro' AS tipo, '5' AS padrao, '3' AS minimo, '10' AS maximo, NULL AS formato, 'encarregado de dados (DPO)' AS dono, TRUE AS critico
    UNION ALL SELECT 'sadt.portalBloqueioMinutos' AS chave, 'Minutos de bloqueio do acesso ao portal depois de esgotar as tentativas' AS descricao, 'inteiro' AS tipo, '15' AS padrao, '5' AS minimo, '1440' AS maximo, NULL AS formato, 'encarregado de dados (DPO)' AS dono, TRUE AS critico
    UNION ALL SELECT 'sadt.portalSessaoMinutos' AS chave, 'Minutos de validade da sessão do portal de resultados' AS descricao, 'inteiro' AS tipo, '20' AS padrao, '5' AS minimo, '120' AS maximo, NULL AS formato, 'encarregado de dados (DPO)' AS dono, TRUE AS critico
    UNION ALL SELECT 'sadt.validadeOrcamentoDias' AS chave, 'Validade padrão do orçamento particular de exames, em dias' AS descricao, 'inteiro' AS tipo, '30' AS padrao, '1' AS minimo, '180' AS maximo, NULL AS formato, 'recepção do diagnóstico' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.numeracaoExame' AS chave, 'Como o número do exame do setor reinicia: contínua, por ano, por mês ou por dia (laboratório)' AS descricao, 'lista' AS tipo, 'continua' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.prefixoNumeracao' AS chave, 'Prefixo impresso antes do número do exame do setor (letras maiúsculas, dígitos e hífen; vazio: sem prefixo) (laboratório)' AS descricao, 'texto' AS tipo, '' AS padrao, NULL AS minimo, NULL AS maximo, '^[A-Z0-9-]{0,10}$' AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.viasLaudo' AS chave, 'Vias impressas do laudo do setor na entrega (laboratório)' AS descricao, 'inteiro' AS tipo, '1' AS padrao, '1' AS minimo, '5' AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.imprimeResponsavelTecnico' AS chave, 'Imprime o responsável técnico do setor no laudo (laboratório)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'responsável técnico do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.imprimeEtiquetaNaColeta' AS chave, 'Imprime a etiqueta da amostra ou do exame no momento da coleta ou do recebimento (laboratório)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.exigeCid' AS chave, 'Exige o CID (Classificação Internacional de Doenças) no pedido de exame do setor (laboratório)' AS descricao, 'booleano' AS tipo, 'false' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.exigeSolicitante' AS chave, 'Exige o profissional solicitante no pedido de exame do setor (laboratório)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.laboratorio.exigeMaterial' AS chave, 'Exige o material biológico no pedido de exame do setor (laboratório)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.numeracaoExame' AS chave, 'Como o número do exame do setor reinicia: contínua, por ano, por mês ou por dia (imagem)' AS descricao, 'lista' AS tipo, 'continua' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.prefixoNumeracao' AS chave, 'Prefixo impresso antes do número do exame do setor (letras maiúsculas, dígitos e hífen; vazio: sem prefixo) (imagem)' AS descricao, 'texto' AS tipo, '' AS padrao, NULL AS minimo, NULL AS maximo, '^[A-Z0-9-]{0,10}$' AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.viasLaudo' AS chave, 'Vias impressas do laudo do setor na entrega (imagem)' AS descricao, 'inteiro' AS tipo, '1' AS padrao, '1' AS minimo, '5' AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.imprimeResponsavelTecnico' AS chave, 'Imprime o responsável técnico do setor no laudo (imagem)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'responsável técnico do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.imprimeEtiquetaNaColeta' AS chave, 'Imprime a etiqueta da amostra ou do exame no momento da coleta ou do recebimento (imagem)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.exigeCid' AS chave, 'Exige o CID (Classificação Internacional de Doenças) no pedido de exame do setor (imagem)' AS descricao, 'booleano' AS tipo, 'false' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.exigeSolicitante' AS chave, 'Exige o profissional solicitante no pedido de exame do setor (imagem)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.imagem.exigeMaterial' AS chave, 'Exige o material biológico no pedido de exame do setor (imagem)' AS descricao, 'booleano' AS tipo, 'false' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.numeracaoExame' AS chave, 'Como o número do exame do setor reinicia: contínua, por ano, por mês ou por dia (métodos gráficos)' AS descricao, 'lista' AS tipo, 'continua' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.prefixoNumeracao' AS chave, 'Prefixo impresso antes do número do exame do setor (letras maiúsculas, dígitos e hífen; vazio: sem prefixo) (métodos gráficos)' AS descricao, 'texto' AS tipo, '' AS padrao, NULL AS minimo, NULL AS maximo, '^[A-Z0-9-]{0,10}$' AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.viasLaudo' AS chave, 'Vias impressas do laudo do setor na entrega (métodos gráficos)' AS descricao, 'inteiro' AS tipo, '1' AS padrao, '1' AS minimo, '5' AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.imprimeResponsavelTecnico' AS chave, 'Imprime o responsável técnico do setor no laudo (métodos gráficos)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'responsável técnico do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.imprimeEtiquetaNaColeta' AS chave, 'Imprime a etiqueta da amostra ou do exame no momento da coleta ou do recebimento (métodos gráficos)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.exigeCid' AS chave, 'Exige o CID (Classificação Internacional de Doenças) no pedido de exame do setor (métodos gráficos)' AS descricao, 'booleano' AS tipo, 'false' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.exigeSolicitante' AS chave, 'Exige o profissional solicitante no pedido de exame do setor (métodos gráficos)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.metodosGraficos.exigeMaterial' AS chave, 'Exige o material biológico no pedido de exame do setor (métodos gráficos)' AS descricao, 'booleano' AS tipo, 'false' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.numeracaoExame' AS chave, 'Como o número do exame do setor reinicia: contínua, por ano, por mês ou por dia (endoscopia)' AS descricao, 'lista' AS tipo, 'continua' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.prefixoNumeracao' AS chave, 'Prefixo impresso antes do número do exame do setor (letras maiúsculas, dígitos e hífen; vazio: sem prefixo) (endoscopia)' AS descricao, 'texto' AS tipo, '' AS padrao, NULL AS minimo, NULL AS maximo, '^[A-Z0-9-]{0,10}$' AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.viasLaudo' AS chave, 'Vias impressas do laudo do setor na entrega (endoscopia)' AS descricao, 'inteiro' AS tipo, '1' AS padrao, '1' AS minimo, '5' AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.imprimeResponsavelTecnico' AS chave, 'Imprime o responsável técnico do setor no laudo (endoscopia)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'responsável técnico do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.imprimeEtiquetaNaColeta' AS chave, 'Imprime a etiqueta da amostra ou do exame no momento da coleta ou do recebimento (endoscopia)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.exigeCid' AS chave, 'Exige o CID (Classificação Internacional de Doenças) no pedido de exame do setor (endoscopia)' AS descricao, 'booleano' AS tipo, 'false' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.exigeSolicitante' AS chave, 'Exige o profissional solicitante no pedido de exame do setor (endoscopia)' AS descricao, 'booleano' AS tipo, 'true' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'diretoria clínica' AS dono, FALSE AS critico
    UNION ALL SELECT 'sadt.endoscopia.exigeMaterial' AS chave, 'Exige o material biológico no pedido de exame do setor (endoscopia)' AS descricao, 'booleano' AS tipo, 'false' AS padrao, NULL AS minimo, NULL AS maximo, NULL AS formato, 'coordenação do setor' AS dono, FALSE AS critico
  ) x
  JOIN (SELECT MIN(id) AS id FROM modulo_sistema WHERE codigo = 'sadt') m;
